/**
 * Flashcards: the deck list with each deck's counts by status, a deck's
 * own page, a missing deck, and the card review at
 * /flashcards/[deckId]/review: Show answer, rating with keys 1 to 4 (which
 * do nothing before the answer shows or once the review is done), "?" and
 * the switch that turns single-key shortcuts off, the tab title following
 * the screen, the completion screen, the review scope surviving a reload,
 * and a review by touch on a small phone.
 *
 * Every test has its own identity (testUser) with one deck generated by
 * the mock AI from one uploaded file, so counts never include another
 * test's cards and the AI rate limit is per test. Scheduling (SM-2,
 * intervals, exam caps) is covered by the spaced-repetition and
 * flashcard-review unit tests.
 */
import type { APIRequestContext, Page } from "@playwright/test";
import { test, expect, createDeck, getJson, loggedStatus } from "./fixtures";

type Rating = "AGAIN" | "HARD" | "GOOD" | "EASY";

interface StudyData {
  cards: { id: string; front: string; back: string }[];
  stats: { newCount: number; learningCount: number; reviewCount: number; masteredCount: number; dueCount: number };
}

const studyData = (api: APIRequestContext, deckId: string) =>
  getJson<StudyData>(api, `/api/flashcards/${deckId}/study?scope=all`);

async function rate(api: APIRequestContext, deckId: string, cardId: string, rating: Rating) {
  const response = await api.post(`/api/flashcards/${deckId}/review`, { data: { card_id: cardId, rating } });
  expect(response.status(), await response.text()).toBe(200);
}

/** The review's progress bar; its value counts cards rated Hard or better. */
const progress = (page: Page) => page.getByRole("progressbar", { name: "Review progress" });

const front = (page: Page) => page.getByRole("heading", { level: 1 });

const ratings = (page: Page) => page.getByRole("group", { name: "How well did you know it?" });

/** A rating button, named "Good, next review in 1 day". */
const ratingButton = (page: Page, label: "Again" | "Hard" | "Good" | "Easy") =>
  ratings(page).getByRole("button", { name: new RegExp(`^${label}\\b`) });

/** Every rating the page sends, in order. */
function recordRatings(page: Page): Rating[] {
  const sent: Rating[] = [];
  page.on("request", (request) => {
    if (request.method() === "POST" && /\/api\/flashcards\/[^/]+\/review$/.test(request.url())) {
      sent.push(request.postDataJSON().rating);
    }
  });
  return sent;
}

test("the deck list counts cards by status, and a deck opens on its cards", { tag: "@mobile" }, async ({ testUser, testUserPage: page }) => {
  const deck = await createDeck(testUser.api);
  await rate(testUser.api, deck.id, deck.cards[0].id, "GOOD");

  await page.goto("/flashcards");
  await expect(page.getByRole("heading", { level: 2, name: "2 cards due today" })).toBeVisible();
  const card = page.getByRole("region", { name: deck.course }).getByRole("article", { name: deck.title });
  await expect(card).toContainText("3 cards");
  await expect(card).toContainText("AI-written");
  const counts = `
    - term: New
    - definition: "2"
    - term: Learning
    - definition: "0"
    - term: Reviewing
    - definition: "1"
    - term: Mastered
    - definition: "0"
  `;
  await expect(card).toMatchAriaSnapshot(counts);
  await expect(card.getByText("2 due today")).toBeVisible();
  await expect(card.getByRole("link", { name: "Review due cards" })).toHaveAttribute("href", `/flashcards/${deck.id}/review`);

  await card.getByRole("link", { name: deck.title }).click();
  await expect(page).toHaveURL(`/flashcards/${deck.id}`);
  await expect(page).toHaveTitle(`${deck.title} · Study Bot`);
  await expect(page.getByRole("heading", { level: 2, name: deck.title })).toBeVisible();
  await expect(page.getByRole("region", { name: "Cards by status" })).toMatchAriaSnapshot(counts);
  const rows = page.getByRole("region", { name: "Cards", exact: true }).getByRole("listitem");
  await expect(rows).toHaveCount(3);
  for (const [i, { front: text }] of deck.cards.entries()) await expect(rows.nth(i)).toContainText(text);
  await expect(rows.first()).toContainText("Reviewing");
  await expect(rows.nth(1)).toContainText("New");
});

test.describe(() => {
  // Chromium logs the 404 document response as a console error.
  test.use({ allowConsoleErrors: [loggedStatus(404)] });

  test("a missing deck says so, in the page and the tab", async ({ testUserPage: page }) => {
    // The review checks the deck before it streams, so the status is a real 404
    const review = await page.goto("/flashcards/no-such-deck/review");
    expect(review?.status()).toBe(404);
    await expect(page.getByRole("heading", { name: "Deck not found" })).toBeVisible();
    await expect(page).toHaveTitle("Deck not found · Study Bot");
    await expect(page.getByRole("link", { name: "Go to Flashcards" })).toHaveAttribute("href", "/flashcards");

    // So does the deck page: no loading boundary streams ahead of its check
    const deck = await page.goto("/flashcards/no-such-deck");
    expect(deck?.status()).toBe(404);
    await expect(page.getByRole("heading", { level: 2, name: "Deck not found" })).toBeVisible();
    await expect(page).toHaveTitle("Deck not found · Study Bot");
  });
});

test("Show answer, then keys 1 to 4 rate; keys do nothing before the answer or after the last card", async ({
  testUser,
  testUserPage: page,
}) => {
  test.slow();
  const deck = await createDeck(testUser.api);
  const [c1, c2, c3] = deck.cards;
  const sent = recordRatings(page);
  await page.goto(`/flashcards/${deck.id}/review`);
  await expect(page).toHaveTitle(`Card 1 of 3 · ${deck.title} · Study Bot`);

  await test.step("before the answer shows, number keys do nothing", async () => {
    await expect(front(page)).toHaveText(c1.front);
    await expect(front(page)).toBeFocused();
    for (const key of ["1", "2", "3", "4"]) await page.keyboard.press(key);
    await expect(page.getByRole("button", { name: "Show answer" })).toBeVisible();
    await expect(page.getByRole("region", { name: "Answer" })).toHaveCount(0);
    await expect(progress(page)).toHaveAttribute("aria-valuenow", "0");
  });

  await test.step("Space shows the answer and each rating shows its key", async () => {
    await page.keyboard.press("Space");
    const answer = page.getByRole("region", { name: "Answer" });
    await expect(answer).toBeFocused();
    await expect(answer).toContainText(c1.back);
    await expect(answer).toContainText("AI-written");
    for (const [label, key] of [["Again", "1"], ["Hard", "2"], ["Good", "3"], ["Easy", "4"]] as const) {
      await expect(ratingButton(page, label).getByText(key, { exact: true })).toBeVisible();
    }
  });

  await test.step("1 is Again: the card comes back at the end", async () => {
    await expect(ratingButton(page, "Again")).toHaveAccessibleName("Again, next review in 10 min");
    await page.keyboard.press("1");
    await expect(front(page)).toHaveText(c2.front);
    await expect(front(page)).toBeFocused();
    await expect(progress(page)).toHaveAttribute("aria-valuenow", "0");
    // No card is done yet, so the tab still counts the first
    await expect(page).toHaveTitle(`Card 1 of 3 · ${deck.title} · Study Bot`);
  });

  await test.step("2, 3 and 4 rate Hard, Good and Easy", async () => {
    for (const [key, next, done] of [
      ["2", c3.front, "1"],
      ["3", c1.front, "2"],
    ] as const) {
      await page.keyboard.press("Space");
      await expect(page.getByRole("region", { name: "Answer" })).toBeFocused();
      await page.keyboard.press(key);
      await expect(front(page)).toHaveText(next);
      await expect(progress(page)).toHaveAttribute("aria-valuenow", done);
      await expect(page).toHaveTitle(`Card ${Number(done) + 1} of 3 · ${deck.title} · Study Bot`);
    }
    await page.keyboard.press("Space");
    await expect(page.getByRole("region", { name: "Answer" })).toBeFocused();
    await page.keyboard.press("4");
  });

  await test.step("the completion screen sums up the review and ignores the keys", async () => {
    const done = page.getByRole("heading", { level: 1, name: "Deck reviewed" });
    await expect(done).toBeFocused();
    await expect(page).toHaveTitle(`Deck reviewed · ${deck.title} · Study Bot`);
    const main = page.getByRole("main");
    await expect(main.getByText(`3 cards reviewed in ${deck.title}.`)).toBeVisible();
    const summary = `
      - term: Again
      - definition: "1"
      - term: Hard
      - definition: "1"
      - term: Good
      - definition: "1"
      - term: Easy
      - definition: "1"
    `;
    await expect(main).toMatchAriaSnapshot(summary);
    await expect(progress(page)).toHaveAttribute("aria-valuenow", "3");

    for (const key of ["1", "2", "3", "4", "Space"]) await page.keyboard.press(key);
    await expect(done).toBeVisible();
    await expect(main).toMatchAriaSnapshot(summary);
    expect(sent).toEqual(["AGAIN", "HARD", "GOOD", "EASY"]);
    await expect(main.getByRole("link", { name: "Go to Flashcards" })).toHaveAttribute("href", "/flashcards");
  });

  await test.step("the ratings are saved: nothing is new or due", async () => {
    const { stats } = await studyData(testUser.api, deck.id);
    expect(stats).toMatchObject({ newCount: 0, dueCount: 0 });
  });
});

test("? and the switch for single-key shortcuts: the keys turn off, and they stay off", async ({
  testUser,
  testUserPage: page,
}) => {
  const deck = await createDeck(testUser.api);
  const sent = recordRatings(page);
  await page.goto(`/flashcards/${deck.id}/review`);
  await expect(front(page)).toBeFocused();

  const help = page.getByRole("button", { name: "Keyboard shortcuts" });
  const popover = page.getByRole("dialog", { name: "Keyboard shortcuts" });
  const single = popover.getByRole("switch", { name: "Single-key shortcuts" });

  // ? opens the shortcuts from the keyboard, switch included
  await page.keyboard.press("?");
  await expect(single).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(popover).toBeHidden();

  await help.click();
  await expect(popover).toContainText("The same setting applies in study sessions.");
  await expect(single).toBeChecked();
  await single.click();
  await expect(single).not.toBeChecked();
  await page.keyboard.press("Escape");
  await expect(popover).toBeHidden();
  await expect(help).toBeFocused();
  // ? is a single key too, so it's off now; the button still opens the help
  await page.keyboard.press("?");
  await expect(popover).toBeHidden();

  await page.getByRole("button", { name: "Show answer" }).click();
  await expect(ratingButton(page, "Good")).toBeVisible();
  await expect(ratingButton(page, "Good").getByText("3", { exact: true })).toHaveCount(0);
  await page.keyboard.press("3");
  await expect(progress(page)).toHaveAttribute("aria-valuenow", "0");
  await expect(front(page)).toHaveText(deck.cards[0].front);
  expect(sent).toEqual([]);

  // The buttons still rate, and Space still shows the answer.
  await ratingButton(page, "Good").click();
  await expect(front(page)).toHaveText(deck.cards[1].front);
  await expect(front(page)).toBeFocused();
  await page.keyboard.press("Space");
  await expect(page.getByRole("region", { name: "Answer" })).toContainText(deck.cards[1].back);
  expect(sent).toEqual(["GOOD"]);

  await page.reload();
  await expect(front(page)).toBeFocused();
  await help.click();
  await expect(single).not.toBeChecked();
});

test("the review scope in the URL survives a reload", async ({ testUser, testUserPage: page }) => {
  const deck = await createDeck(testUser.api);
  for (const card of deck.cards) await rate(testUser.api, deck.id, card.id, "GOOD");

  await page.goto(`/flashcards/${deck.id}/review`);
  await expect(front(page)).toHaveText(`Nothing due in ${deck.title}`);
  await expect(page).toHaveTitle(`Nothing due · ${deck.title} · Study Bot`);
  await page.getByRole("button", { name: "Review deck" }).click();

  // Reviewing the whole deck puts ?scope=all in the URL, so a reload keeps it.
  await expect(page).toHaveURL(`/flashcards/${deck.id}/review?scope=all`);
  await expect(front(page)).toHaveText(deck.cards[0].front);
  await expect(progress(page)).toHaveAttribute("aria-valuemax", "3");

  await page.reload();
  await expect(page).toHaveURL(`/flashcards/${deck.id}/review?scope=all`);
  await expect(front(page)).toHaveText(deck.cards[0].front);
  await expect(progress(page)).toHaveAttribute("aria-valuemax", "3");
});

test("a review by touch on a small phone", { tag: "@mobile" }, async ({ isMobile, testUser, testUserPage: page }) => {
  test.skip(!isMobile, "Phone layout only");
  // 320px wide, where the counts used to wrap in the top bar and push the question under it
  await page.setViewportSize({ width: 320, height: 568 });
  const deck = await createDeck(testUser.api);
  await page.goto(`/flashcards/${deck.id}/review`);
  await expect(front(page)).toHaveText(deck.cards[0].front);
  // A phone or tablet can have a keyboard (or switch software that sends keys), so the
  // shortcuts and their off switch stay one tap away.
  await expect(page.getByRole("button", { name: "Keyboard shortcuts" })).toBeVisible();
  // The counts sit under the card, once
  await expect(page.getByRole("term").filter({ hasText: "Mastered" })).toHaveCount(1);
  const leave = page.getByRole("link", { name: "Leave review" });

  for (const card of deck.cards) {
    await expect(front(page)).toHaveText(card.front);
    await page.getByRole("button", { name: "Show answer" }).tap();
    await expect(page.getByRole("region", { name: "Answer" })).toContainText(card.back);
    // The question stays clear of the top bar (the close button's row) when the answer shows
    const bar = await leave.boundingBox();
    const question = await front(page).boundingBox();
    expect(question!.y).toBeGreaterThanOrEqual(bar!.y + bar!.height);
    await ratingButton(page, "Good").tap();
  }

  await expect(page.getByRole("heading", { level: 1, name: "Deck reviewed" })).toBeVisible();
  await page.getByRole("link", { name: "Go to Flashcards" }).tap();
  await expect(page).toHaveURL("/flashcards");
  await expect(page.getByRole("heading", { level: 2, name: "Nothing due today" })).toBeVisible();
});
